import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env=None):
    if env is None:
        env = os.environ
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            path = key[len(env_prefix):].lower().split('__')
            current = config
            for part in path[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            current[path[-1]] = value
    return config

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'a': 1, 'b': 2}
    assert load_config(defaults) == {'a': 1, 'b': 2}

def test_toml():
    with open('config.toml', 'wb') as f:
        f.write(b'a = 3\nb = 4')
    assert load_config({'a': 1, 'b': 2}, 'config.toml') == {'a': 3, 'b': 4}

def test_env():
    os.environ['APP__A'] = '5'
    assert load_config({'a': 1}, env_prefix='APP__') == {'a': 5}

def test_precedence():
    with open('config.toml', 'wb') as f:
        f.write(b'a = 6')
    os.environ['APP__A'] = '7'
    assert load_config({'a': 1}, 'config.toml', env_prefix='APP__') == {'a': 7}

def test_nested():
    os.environ['APP__SERVER__PORT'] = '8080'
    assert load_config({'server': {'port': 80}}, env_prefix='APP__') == {'server': {'port': 8080}}

def test_coercion():
    os.environ['APP__PORT'] = '8080'
    assert load_config({'port': 80}, env_prefix='APP__') == {'port': 8080}

def test_missing_toml():
    assert load_config({'a': 1}, 'missing.toml') == {'a': 1}

def test_missing_env():
    with pytest.raises(ConfigError):
        load_config({}, env_prefix='APP__')

def test_invalid_type():
    os.environ['APP__PORT'] = 'invalid'
    with pytest.raises(ConfigError):
        load_config({'port': 80}, env_prefix='APP__')

